import React from 'react';
import { CoasterCar } from './index';

const previews = {
  componentName: 'CoasterCar',
  importPath: 'components/CoasterCar',
  previews: [
    { name: '3D rig', description: "A single wooden-coaster car with seated riders, modelled from the RCT2 vehicle sprite. Drag to orbit.", render: () => <CoasterCar /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';

// A single wooden-coaster car, modelled from the RCT2 sprite: a rounded orange
// open-top tub on a dark chassis, two rows of seated riders (pink / gold
// shirts), a sloped nose, and four wheels. Exported as a builder so the
// WoodenCoaster rig can put a whole train on the track.
export function buildCoasterCar(t: typeof THREE): THREE.Group {
  const g = new t.Group();
  const ORANGE = 0xe0601a;
  const ORANGE_D = 0xb5480f;
  const DARK = 0x26262b;
  const SEAT = 0x1c1c20;
  const SKIN = 0xe0a878;

  // chassis
  g.add(box(t, [0.56, 0.12, 0.98], DARK, [0, 0.0, 0], { metal: 0.3, rough: 0.6 }));
  // outer tub
  g.add(box(t, [0.62, 0.36, 1.02], ORANGE, [0, 0.24, 0], { rough: 0.5 }));
  // side rails / trim
  g.add(box(t, [0.66, 0.06, 1.04], ORANGE_D, [0, 0.42, 0], { rough: 0.5 }));
  // hollow interior
  g.add(box(t, [0.48, 0.26, 0.88], SEAT, [0, 0.32, 0]));
  // sloped nose (front, +z)
  g.add(box(t, [0.62, 0.32, 0.22], ORANGE, [0, 0.24, 0.56], { rotX: -0.6, rough: 0.5 }));

  // two rows of riders
  const shirts = [0xe060a0, 0xf0c020];
  [-0.2, 0.24].forEach((z, i) => {
    g.add(box(t, [0.5, 0.2, 0.05], SEAT, [0, 0.36, z - 0.14])); // seat back
    g.add(box(t, [0.3, 0.22, 0.26], shirts[i], [0, 0.46, z], { rough: 0.7 })); // torso
    g.add(ball(t, 0.1, SKIN, [0, 0.64, z])); // head
    // lap bar
    g.add(box(t, [0.34, 0.04, 0.04], DARK, [0, 0.5, z + 0.12], { metal: 0.5, rough: 0.4 }));
  });

  // wheels
  const wheel = (x: number, z: number) =>
    cyl(t, 0.1, 0.1, 0.07, DARK, [x, -0.03, z], { rotZ: Math.PI / 2, metal: 0.6, rough: 0.4 });
  [
    [-0.31, 0.34],
    [0.31, 0.34],
    [-0.31, -0.34],
    [0.31, -0.34],
  ].forEach(([x, z]) => g.add(wheel(x, z)));

  return g;
}

export function CoasterCar() {
  return (
    <Stage
      distance={4.4}
      targetY={0.45}
      build={(t, g) => {
        const RAIL = 0x8b8f96;
        const TIE = 0x6b4626;
        for (let z = -1.4; z <= 1.4; z += 0.4) g.add(box(t, [0.98, 0.06, 0.12], TIE, [0, 0.02, z]));
        g.add(box(t, [0.07, 0.08, 3.0], RAIL, [-0.32, 0.09, 0], { metal: 0.8, rough: 0.35 }));
        g.add(box(t, [0.07, 0.08, 3.0], RAIL, [0.32, 0.09, 0], { metal: 0.8, rough: 0.35 }));
        const car = buildCoasterCar(t);
        car.position.y = 0.2;
        g.add(car);
        return (time) => {
          car.position.y = 0.2 + Math.sin(time * 2) * 0.02;
          car.rotation.z = Math.sin(time * 1.3) * 0.02;
        };
      }}
    />
  );
}

import React from 'react';
import { Guest } from './index';

const previews = {
  componentName: 'Guest',
  importPath: 'components/Guest',
  previews: [
    { name: '3D rig', description: "A park guest with an animated walk cycle, modelled from the RCT2 peep sprite. Drag to orbit.", render: () => <Guest /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, ball } from '../Stage';

// A park guest modelled from the RCT2 peep sprite: skin head + brown hair,
// red t-shirt torso, navy trousers, brown shoes. Arms and legs are on pivots
// so the guest plays a continuous walk cycle (as the sprite animates).
export function Guest() {
  return (
    <Stage
      distance={3.1}
      targetY={0.55}
      build={(t, g) => {
        const SKIN = 0xe0a878;
        const HAIR = 0x4a3018;
        const SHIRT = 0xc21a1a;
        const TROU = 0x26305e;
        const SHOE = 0x2a1c10;

        const guest = new t.Group();
        g.add(guest);

        guest.add(box(t, [0.26, 0.14, 0.18], TROU, [0, 0.52, 0], { rough: 0.9 })); // hips
        guest.add(box(t, [0.3, 0.32, 0.2], SHIRT, [0, 0.74, 0], { rough: 0.8 })); // torso
        guest.add(ball(t, 0.12, SKIN, [0, 0.99, 0])); // head
        const hair = ball(t, 0.13, HAIR, [0, 1.03, -0.01]);
        hair.scale.y = 0.72;
        guest.add(hair);

        const limb = (px: number, py: number, meshColor: number, len: number, handColor?: number) => {
          const pivot = new t.Group();
          pivot.position.set(px, py, 0);
          pivot.add(box(t, [0.09, len, 0.11], meshColor, [0, -len / 2, 0], { rough: 0.85 }));
          if (handColor != null) pivot.add(ball(t, 0.05, handColor, [0, -len, 0]));
          guest.add(pivot);
          return pivot;
        };
        const armL = limb(-0.19, 0.88, SHIRT, 0.32, SKIN);
        const armR = limb(0.19, 0.88, SHIRT, 0.32, SKIN);
        const legL = limb(-0.08, 0.46, TROU, 0.4);
        const legR = limb(0.08, 0.46, TROU, 0.4);
        legL.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03]));
        legR.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03]));

        return (time) => {
          const s = Math.sin(time * 5);
          legL.rotation.x = s * 0.5;
          legR.rotation.x = -s * 0.5;
          armL.rotation.x = -s * 0.45;
          armR.rotation.x = s * 0.45;
          guest.position.y = Math.abs(Math.cos(time * 5)) * 0.03;
        };
      }}
    />
  );
}

import React from 'react';
import { OakTree } from './index';

const previews = {
  componentName: 'OakTree',
  importPath: 'components/OakTree',
  previews: [
    { name: '3D rig', description: "An oak tree with chunky foliage that sways, modelled from the RCT2 scenery sprite. Drag to orbit.", render: () => <OakTree /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, cyl, ball } from '../Stage';

// An oak tree modelled from the RCT2 scenery sprite: a short brown trunk under
// a cluster of chunky, flat-shaded olive/green foliage blobs. Sways gently in
// the breeze.
export function OakTree() {
  return (
    <Stage
      distance={6}
      targetY={1.2}
      build={(t, g) => {
        const BARK = 0x5a3d22;
        const greens = [0x6f8f3a, 0x5c7d2e, 0x86a84a, 0x7c9a40];
        const tree = new t.Group();
        g.add(tree);
        tree.add(cyl(t, 0.14, 0.2, 1.1, BARK, [0, 0.55, 0], { rough: 1 }));
        const blobs: [number, number, number, number, number][] = [
          [0, 1.55, 0, 0.74, greens[0]],
          [-0.52, 1.36, 0.18, 0.52, greens[1]],
          [0.5, 1.42, -0.12, 0.56, greens[2]],
          [0.12, 1.9, -0.05, 0.52, greens[3]],
          [-0.22, 1.58, -0.46, 0.46, greens[1]],
          [0.36, 1.64, 0.42, 0.47, greens[2]],
          [-0.05, 1.28, 0.5, 0.44, greens[0]],
        ];
        blobs.forEach(([x, y, z, r, c]) => tree.add(ball(t, r, c, [x, y, z], { flat: true, rough: 1 })));
        return (time) => {
          tree.rotation.z = Math.sin(time * 1.1) * 0.025;
          tree.rotation.x = Math.cos(time * 0.9) * 0.02;
        };
      }}
    />
  );
}

