};

export default previews;

import React from 'react';
import { Stage, box } from '../Stage';

// A paved park road tile modelled from the RCT2 tarmac footpath: an asphalt
// slab with light stone kerbs on two edges and a dashed centre line.
export function Road() {
  return (
    <Stage
      distance={4.6}
      targetY={0.15}
      build={(t, g) => {
        const ASP = 0x6b6b6e;
        const ASP2 = 0x5d5d61;
        const KERB = 0xb9b6ad;
        const LINE = 0xe8c64a;
        // asphalt slab
        g.add(box(t, [2.0, 0.12, 2.0], ASP, [0, 0.06, 0], { rough: 0.97 }));
        // subtle patch variation
        g.add(box(t, [0.9, 0.13, 0.9], ASP2, [0.35, 0.065, -0.2], { rough: 0.97 }));
        // kerbs on two opposite edges
        g.add(box(t, [2.0, 0.16, 0.12], KERB, [0, 0.1, 0.98], { rough: 0.9 }));
        g.add(box(t, [2.0, 0.16, 0.12], KERB, [0, 0.1, -0.98], { rough: 0.9 }));
        // dashed centre line
        for (let x = -0.8; x <= 0.8; x += 0.5) g.add(box(t, [0.3, 0.02, 0.08], LINE, [x, 0.13, 0]));
      }}
    />
  );
}

# Stage

Foundation for every 3D rig. Creates a three.js `WebGLRenderer`, an orbit camera (drag to rotate, auto-rotates when idle), hemisphere + directional sun light with soft shadows, and a grass ground disc. Exposes geometry helpers `box`, `cyl`, `ball`, `mat`.

```tsx
<Stage build={(THREE, group) => {
  group.add(box(THREE, [1,1,1], 0xdd6633, [0,0.5,0]));
  return (t) => { group.rotation.y = t; }; // optional per-frame update
}} />
```

import React from 'react';
import { Stage, box, ball } from './index';

const previews = {
  componentName: 'Stage',
  importPath: 'components/Stage',
  previews: [
    { name: 'Foundation', description: 'Reusable three.js viewport (orbit camera, sun + soft shadows, grass ground). Pass a build(THREE, group) callback.', render: () => (
      <Stage build={(t, g) => { g.add(box(t, [1, 1, 1], 0xdd6633, [0, 0.5, 0])); g.add(ball(t, 0.45, 0x4488cc, [1, 0.45, 0.6])); }} />
    ) },
  ],
};

export default previews;

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Stage — a self-contained three.js viewport used by every 3D rig in this
// design system. It sets up a renderer, an isometric-ish orbit camera (drag to
// rotate, auto-rotates when idle), warm "theme-park" lighting with soft
// shadows, and a grass ground disc. Pass a `build` callback that populates the
// content group and optionally returns a per-frame `update(t)` for animation.
// ---------------------------------------------------------------------------

export type BuildFn = (
  three: typeof THREE,
  group: THREE.Group,
) => ((t: number) => void) | void;

export interface StageProps {
  build: BuildFn;
  height?: number;
  background?: string;
  autoRotate?: boolean;
  /** camera distance from the target */
  distance?: number;
  /** look-at height */
  targetY?: number;
}

// ---- tiny geometry helpers (shared by the rigs) ----
export interface MatOpts {
  rough?: number;
  metal?: number;
  flat?: boolean;
  emissive?: number;
  opacity?: number;
}
export function mat(three: typeof THREE, color: number, o: MatOpts = {}) {
  return new three.MeshStandardMaterial({
    color,
    roughness: o.rough ?? 0.82,
    metalness: o.metal ?? 0.0,
    flatShading: o.flat ?? false,
    emissive: o.emissive ?? 0x000000,
    transparent: o.opacity != null,
    opacity: o.opacity ?? 1,
  });
}
export function box(
  three: typeof THREE,
  dims: [number, number, number],
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts & { rotX?: number; rotY?: number; rotZ?: number } = {},
) {
  const m = new three.Mesh(new three.BoxGeometry(...dims), mat(three, color, o));
  m.position.set(...pos);
  if (o.rotX) m.rotation.x = o.rotX;
  if (o.rotY) m.rotation.y = o.rotY;
  if (o.rotZ) m.rotation.z = o.rotZ;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
export function cyl(
  three: typeof THREE,
  rTop: number,
  rBot: number,
  h: number,
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts & { rotX?: number; rotY?: number; rotZ?: number; seg?: number } = {},
) {
  const m = new three.Mesh(new three.CylinderGeometry(rTop, rBot, h, o.seg ?? 16), mat(three, color, o));
  m.position.set(...pos);
  if (o.rotX) m.rotation.x = o.rotX;
  if (o.rotY) m.rotation.y = o.rotY;
  if (o.rotZ) m.rotation.z = o.rotZ;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
export function ball(
  three: typeof THREE,
  r: number,
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts = {},
) {
  const m = new three.Mesh(new three.IcosahedronGeometry(r, o.flat ? 1 : 2), mat(three, color, o));
  m.position.set(...pos);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export function Stage({
  build,
  height = 340,
  background = '#9ec7d8',
  autoRotate = true,
  distance = 8,
  targetY = 0.7,
}: StageProps) {
  const ref = useRef<HTMLDivElement>(null);
  const buildRef = useRef(build);
  buildRef.current = build;

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let w = el.clientWidth || 480;
    const h = height;

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(w, h);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    el.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(background);
    scene.fog = new THREE.Fog(new THREE.Color(background).getHex(), distance * 2.2, distance * 4.5);

    const camera = new THREE.PerspectiveCamera(34, w / h, 0.1, 200);
    const target = new THREE.Vector3(0, targetY, 0);

    // lighting — warm sun + cool sky fill
    scene.add(new THREE.HemisphereLight(0xdff0ff, 0x6b7a55, 0.65));
    const sun = new THREE.DirectionalLight(0xfff0d6, 1.15);
    sun.position.set(6, 11, 5);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    const s = 7;
    sun.shadow.camera.left = -s;
    sun.shadow.camera.right = s;
    sun.shadow.camera.top = s;
    sun.shadow.camera.bottom = -s;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 40;
    sun.shadow.bias = -0.0004;
    scene.add(sun);

    // grass ground
    const ground = new THREE.Mesh(
      new THREE.CircleGeometry(distance * 1.6, 64),
      new THREE.MeshStandardMaterial({ color: 0x6f9e54, roughness: 1 }),
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    const group = new THREE.Group();
    scene.add(group);
    const update = buildRef.current(THREE, group) || undefined;

    // orbit state
    let az = Math.PI * 0.25;
    let el2 = Math.PI * 0.28;
    let dragging = false;
    let px = 0;
    let py = 0;
    const applyCam = () => {
      const r = distance;
      camera.position.set(
        target.x + r * Math.cos(el2) * Math.sin(az),
        target.y + r * Math.sin(el2),
        target.z + r * Math.cos(el2) * Math.cos(az),
      );
      camera.lookAt(target);
    };
    const dom = renderer.domElement;
    dom.style.cursor = 'grab';
    const down = (e: PointerEvent) => {
      dragging = true;
      px = e.clientX;
      py = e.clientY;
      dom.style.cursor = 'grabbing';
      dom.setPointerCapture(e.pointerId);
    };
    const move = (e: PointerEvent) => {
      if (!dragging) return;
      az -= (e.clientX - px) * 0.01;
      el2 = Math.max(0.08, Math.min(1.45, el2 + (e.clientY - py) * 0.01));
      px = e.clientX;
      py = e.clientY;
    };
    const up = (e: PointerEvent) => {
      dragging = false;
      dom.style.cursor = 'grab';
      try {
        dom.releasePointerCapture(e.pointerId);
      } catch {
        /* noop */
      }
    };
    dom.addEventListener('pointerdown', down);
    dom.addEventListener('pointermove', move);
    dom.addEventListener('pointerup', up);

    const clock = new THREE.Clock();
    let raf = 0;
    const loop = () => {
      const t = clock.getElapsedTime();
      if (autoRotate && !dragging) az += 0.0045;
      applyCam();
      if (update) update(t);
      renderer.render(scene, camera);
      raf = requestAnimationFrame(loop);
    };
    loop();

    const ro = new ResizeObserver(() => {
      w = el.clientWidth || w;
      renderer.setSize(w, h);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    });
    ro.observe(el);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      dom.removeEventListener('pointerdown', down);
      dom.removeEventListener('pointermove', move);
      dom.removeEventListener('pointerup', up);
      renderer.dispose();
      scene.traverse((obj) => {
        const anyObj = obj as unknown as { geometry?: THREE.BufferGeometry; material?: THREE.Material | THREE.Material[] };
        anyObj.geometry?.dispose?.();
        const m = anyObj.material;
        if (Array.isArray(m)) m.forEach((mm) => mm.dispose());
        else m?.dispose?.();
      });
      if (dom.parentNode === el) el.removeChild(dom);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return <div ref={ref} style={{ width: '100%', height, borderRadius: 12, overflow: 'hidden' }} />;
}

import React from 'react';
import { WoodenCoaster } from './index';

const previews = {
  componentName: 'WoodenCoaster',
  importPath: 'components/WoodenCoaster',
  previews: [
    { name: '3D rig', description: "Wooden roller-coaster track + riding train, modelled from the RCT2 sprite (rails, ties, wooden support bents). Drag to orbit.", render: () => <WoodenCoaster /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box } from '../Stage';
import { buildCoasterCar } from '../CoasterCar';

// A straight run of wooden roller-coaster track modelled from the RCT2 sprite:
// two steel running rails on wooden stringers over cross-ties, carried by
// wooden support bents (posts + ledgers + X cross-braces). A two-car train
// rides the length on a loop.
export function WoodenCoaster() {
  return (
    <Stage
      distance={9}
      targetY={1.0}
      build={(t, g) => {
        const WOOD = 0x7a5230;
        const WOOD_D = 0x5f3f24;
        const RAIL = 0x8b8f96;
        const TIE = 0x6b4626;
        const L = 6;
        const y = 1.25;

        // stringers
        g.add(box(t, [0.16, 0.2, L], WOOD, [-0.34, y - 0.18, 0]));
        g.add(box(t, [0.16, 0.2, L], WOOD, [0.34, y - 0.18, 0]));
        // ties
        for (let z = -L / 2 + 0.2; z <= L / 2 - 0.2; z += 0.5)
          g.add(box(t, [1.02, 0.06, 0.14], TIE, [0, y - 0.05, z]));
        // steel rails
        g.add(box(t, [0.07, 0.09, L], RAIL, [-0.34, y + 0.05, 0], { metal: 0.85, rough: 0.32 }));
        g.add(box(t, [0.07, 0.09, L], RAIL, [0.34, y + 0.05, 0], { metal: 0.85, rough: 0.32 }));

        // support bents
        const brace = Math.atan2(y, 1.1);
        const bent = (z: number) => {
          const b = new t.Group();
          [-0.55, 0.55].forEach((x) => b.add(box(t, [0.14, y, 0.14], WOOD, [x, y / 2, 0])));
          b.add(box(t, [1.42, 0.12, 0.12], WOOD_D, [0, 0.28, 0]));
          b.add(box(t, [1.42, 0.12, 0.12], WOOD_D, [0, y - 0.18, 0]));
          b.add(box(t, [1.55, 0.06, 0.05], WOOD_D, [0, y / 2, 0], { rotZ: brace }));
          b.add(box(t, [1.55, 0.06, 0.05], WOOD_D, [0, y / 2, 0], { rotZ: -brace }));
          b.position.z = z;
          g.add(b);
        };
        [-2.2, -0.7, 0.7, 2.2].forEach(bent);

        // riding train (2 cars)
        const cars = [buildCoasterCar(t), buildCoasterCar(t)];
        cars.forEach((c) => {
          c.scale.setScalar(0.92);
          g.add(c);
        });
        const span = L + 2;
        return (time) => {
          const head = ((time * 1.4) % span) - span / 2;
          cars.forEach((c, i) => {
            c.position.set(0, y + 0.16, head - i * 0.95);
          });
        };
      }}
    />
  );
}

